// @generated by Claude Code (Sonnet 5.5) on 2026-11-03 — Helix Tile Manager renderer
(() => {
  const $ = (id) => document.getElementById(id);
  const el = {
    portalUrl: $('portalUrl'), iconBaseUrl: $('iconBaseUrl'), signIn: $('signIn'), check: $('check'),
    status: $('status'), statusText: $('statusText'),
    name: $('name'), description: $('description'), url: $('url'), tileId: $('tileId'), formTitle: $('formTitle'),
    iconSearch: $('iconSearch'), icons: $('icons'), iconName: $('iconName'),
    previewIcon: $('previewIcon'), previewName: $('previewName'), previewDesc: $('previewDesc'), previewUrl: $('previewUrl'),
    save: $('save'), cancelEdit: $('cancelEdit'), message: $('message'),
    tiles: $('tiles'), tilesEmpty: $('tilesEmpty'), refresh: $('refresh'),
    isUrl: $('isUrl'), discover: $('discover'), includeLibs: $('includeLibs'), discoverBox: $('discoverBox'),
    discoverSearch: $('discoverSearch'), discoverCount: $('discoverCount'), discoverList: $('discoverList'),
    discoverMsg: $('discoverMsg'),
    appVersion: $('appVersion'), checkUpdate: $('checkUpdate'), updateStatus: $('updateStatus'),
    openUpdate: $('openUpdate'), reportIssue: $('reportIssue'),
  };
  let discovered = [];

  let selected = ICONS[0];
  let iconChosen = true; // false while editing until the user picks a new icon
  let editId = null;

  const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50);
  const errText = (e) => String(e && e.message || e).replace(/^Error invoking remote method '[^']+': (Error: )?/, '');

  function say(text, kind) {
    el.message.textContent = text || '';
    el.message.className = 'message' + (kind ? ' ' + kind : '');
  }

  function setStatus(on, text) {
    el.status.className = 'status' + (on ? ' on' : '');
    el.statusText.textContent = text;
  }

  function updatePreview() {
    el.previewIcon.innerHTML = renderIcon(selected);
    el.previewName.textContent = el.name.value.trim() || 'Tile name';
    el.previewDesc.textContent = el.description.value.trim() || 'Your description appears here.';
    el.previewUrl.textContent = el.url.value.trim() ? '→ ' + el.url.value.trim() : '';
    el.iconName.textContent = selected.label;
    el.tileId.textContent = editId || 'custom-' + slug(el.name.value);
  }

  function renderIcons() {
    const q = el.iconSearch.value.trim().toLowerCase();
    el.icons.textContent = '';
    ICONS.filter((i) => !q || i.label.toLowerCase().includes(q) || i.key.includes(q)).forEach((icon) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'icon' + (icon === selected ? ' selected' : '');
      b.title = icon.label;
      b.innerHTML = renderIcon(icon) + '<span></span>';
      b.querySelector('span').textContent = icon.label;
      b.addEventListener('click', () => {
        selected = icon;
        iconChosen = true;
        renderIcons();
        updatePreview();
      });
      el.icons.appendChild(b);
    });
    if (!el.icons.children.length) {
      const p = document.createElement('p');
      p.className = 'empty';
      p.textContent = 'No icons match your search.';
      el.icons.appendChild(p);
    }
  }

  function resetForm() {
    editId = null;
    iconChosen = true;
    el.name.value = el.description.value = el.url.value = '';
    el.name.disabled = false;
    el.formTitle.textContent = 'Describe the tile';
    el.save.textContent = 'Create tile';
    el.cancelEdit.classList.add('hidden');
    updatePreview();
  }

  function renderTiles(tiles) {
    el.tiles.textContent = '';
    el.tilesEmpty.textContent = 'No custom tiles yet.';
    el.tilesEmpty.classList.toggle('hidden', tiles.length > 0);
    tiles.forEach((t) => {
      const li = document.createElement('li');
      const thumb = document.createElement('div');
      thumb.className = 'thumb';
      const img = document.createElement('img');
      img.alt = '';
      img.src = t.icon;
      thumb.appendChild(img);
      const meta = document.createElement('div');
      meta.className = 'meta';
      const strong = document.createElement('strong');
      strong.textContent = t.name;
      const span = document.createElement('span');
      span.textContent = t.url;
      meta.append(strong, span);
      const edit = document.createElement('button');
      edit.type = 'button';
      edit.className = 'secondary';
      edit.textContent = 'Edit';
      edit.addEventListener('click', () => startEdit(t));
      const del = document.createElement('button');
      del.type = 'button';
      del.className = 'danger';
      del.textContent = 'Remove';
      del.addEventListener('click', () => removeTile(t));
      li.append(thumb, meta, edit, del);
      el.tiles.appendChild(li);
    });
  }

  function startEdit(t) {
    editId = t.id;
    iconChosen = false;
    el.name.value = t.name;
    el.description.value = t.description;
    el.url.value = t.url;
    const m = /\/icons\/([a-z0-9-]+)\.svg$/.exec(t.icon);
    const known = m && ICONS.find((i) => i.key === m[1]);
    if (known) selected = known;
    el.formTitle.textContent = 'Editing ' + t.name;
    el.save.textContent = 'Save changes';
    el.cancelEdit.classList.remove('hidden');
    renderIcons();
    updatePreview();
    say('Change any field and click Save changes. The tile id stays the same, even if you rename the tile.');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  async function removeTile(t) {
    if (!confirm('Remove the tile "' + t.name + '" for all portal users?')) return;
    try {
      await window.api.deleteApp(t.id);
      if (editId === t.id) resetForm();
      say('Removed "' + t.name + '".', 'ok');
      await loadTiles();
    } catch (e) {
      say(errText(e), 'err');
    }
  }

  async function loadTiles() {
    try {
      renderTiles(await window.api.listApps());
    } catch (e) {
      el.tiles.textContent = '';
      el.tilesEmpty.textContent = 'Sign in to see your tiles.';
      el.tilesEmpty.classList.remove('hidden');
      throw e;
    }
  }

  async function connect(silent) {
    try {
      const me = await window.api.check();
      setStatus(true, 'Connected as ' + me.user + ' (' + me.tenant + ')');
      await loadTiles();
      return true;
    } catch (e) {
      setStatus(false, 'Not connected');
      if (!silent) say(errText(e), 'err');
      return false;
    }
  }

  async function saveSettings() {
    await window.api.saveSettings({ portalUrl: el.portalUrl.value, iconBaseUrl: el.iconBaseUrl.value, isUrl: el.isUrl.value });
  }

  el.signIn.addEventListener('click', async () => {
    say('');
    el.signIn.disabled = true;
    try {
      await saveSettings();
      await window.api.signIn();
      if (await connect(false)) say('Connected.', 'ok');
    } catch (e) {
      say(errText(e), 'err');
    } finally {
      el.signIn.disabled = false;
    }
  });

  el.check.addEventListener('click', async () => {
    say('');
    try {
      await saveSettings();
      if (await connect(false)) say('Connected.', 'ok');
    } catch (e) {
      say(errText(e), 'err');
    }
  });

  el.refresh.addEventListener('click', () => { say(''); connect(false); });

  el.save.addEventListener('click', async () => {
    say('');
    el.save.disabled = true;
    try {
      await saveSettings();
      const res = await window.api.saveApp({
        id: editId,
        name: el.name.value,
        description: el.description.value,
        url: el.url.value,
        iconKey: iconChosen ? selected.key : null,
      });
      const base = 'Tile "' + el.name.value.trim() + '" ' + (res.updated ? 'updated' : 'created') + '.';
      say(res.iconFallback
        ? base + ' No icon site URL is set, so it uses the default portal icon.'
        : base + ' It shows on the portal\'s Custom applications tab.', 'ok');
      resetForm();
      await loadTiles();
    } catch (e) {
      say(errText(e), 'err');
    } finally {
      el.save.disabled = false;
    }
  });

  // --- Innovation Studio discovery ---
  function sayDiscover(text, kind) {
    el.discoverMsg.textContent = text || '';
    el.discoverMsg.className = 'message' + (kind ? ' ' + kind : '');
  }

  function useApp(a) {
    if (!editId) el.name.value = a.name.slice(0, 60);
    el.description.value = a.description || '';
    el.url.value = a.url;
    updatePreview();
    sayDiscover('Filled the tile from "' + a.name + '". Pick an icon, then create the tile.', 'ok');
    el.url.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }

  function renderDiscovered() {
    const q = el.discoverSearch.value.trim().toLowerCase();
    const rows = discovered.filter((a) => !q || (a.name + ' ' + a.id + ' ' + a.description).toLowerCase().includes(q));
    el.discoverList.textContent = '';
    el.discoverCount.textContent = rows.length + ' of ' + discovered.length + ' applications';
    rows.forEach((a) => {
      const li = document.createElement('li');
      const meta = document.createElement('div');
      meta.className = 'meta';
      const strong = document.createElement('strong');
      strong.textContent = a.name;
      const span = document.createElement('span');
      span.textContent = [a.id, a.version && 'v' + a.version, a.developer].filter(Boolean).join('  ·  ');
      const code = document.createElement('code');
      code.textContent = a.url;
      meta.append(strong, span, code);
      const use = document.createElement('button');
      use.type = 'button';
      use.className = 'secondary';
      use.textContent = 'Use URL';
      use.addEventListener('click', () => useApp(a));
      li.append(meta, use);
      el.discoverList.appendChild(li);
    });
  }

  el.discover.addEventListener('click', async () => {
    sayDiscover('Finding applications in Innovation Studio…');
    el.discover.disabled = true;
    try {
      await saveSettings();
      const res = await window.api.discoverApps({ includeLibraries: el.includeLibs.checked });
      discovered = res.apps;
      el.discoverBox.classList.remove('hidden');
      renderDiscovered();
      sayDiscover(discovered.length ? 'Found ' + discovered.length + ' applications on ' + res.origin + '.' : 'No applications found.', discovered.length ? 'ok' : '');
    } catch (e) {
      sayDiscover(errText(e), 'err');
    } finally {
      el.discover.disabled = false;
    }
  });
  el.discoverSearch.addEventListener('input', renderDiscovered);

  // --- Version, update check, issue reporting (footer) ---
  async function runUpdateCheck() {
    el.checkUpdate.disabled = true;
    el.openUpdate.classList.add('hidden');
    el.updateStatus.className = 'update-status';
    el.updateStatus.textContent = 'Checking…';
    try {
      const u = await window.api.checkUpdate();
      if (u.newer) {
        el.updateStatus.className = 'update-status new';
        el.updateStatus.textContent = 'Version ' + u.latest + ' is available.';
        el.openUpdate.classList.remove('hidden');
      } else {
        el.updateStatus.textContent = 'You are up to date.';
      }
    } catch (e) {
      el.updateStatus.className = 'update-status err';
      el.updateStatus.textContent = errText(e);
    } finally {
      el.checkUpdate.disabled = false;
    }
  }

  el.checkUpdate.addEventListener('click', runUpdateCheck);
  el.openUpdate.addEventListener('click', () => window.api.openUpdate().catch((e) => { el.updateStatus.textContent = errText(e); }));
  el.reportIssue.addEventListener('click', () => window.api.openIssues());

  el.cancelEdit.addEventListener('click', () => { resetForm(); say(''); });
  el.iconSearch.addEventListener('input', renderIcons);
  ['name', 'description', 'url'].forEach((k) => el[k].addEventListener('input', updatePreview));

  (async () => {
    renderIcons();
    updatePreview();
    const s = await window.api.getSettings();
    el.portalUrl.value = s.portalUrl;
    el.iconBaseUrl.value = s.iconBaseUrl;
    el.isUrl.value = s.isUrl || '';
    if (s.portalUrl) connect(true);
    window.api.appInfo().then((i) => { el.appVersion.textContent = 'v' + i.version; });
    runUpdateCheck();
  })();
})();
